import{_ as t,o as s,c as a,ah as r}from"./chunks/framework.ChH6X6u6.js";const m=JSON.parse('{"title":"Tableau de bord","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/admin/tableau-de-bord.md","filePath":"src/guide/admin/tableau-de-bord.md"}'),i={name:"guide/admin/tableau-de-bord.md"};function n(l,e,d,o,u,c){return s(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="tableau-de-bord" tabindex="-1">Tableau de bord <a class="header-anchor" href="#tableau-de-bord" aria-label="Permalink to &quot;Tableau de bord&quot;">​</a></h1><p>Le tableau de bord est la page d&#39;accueil de tout compte connecté, mais son contenu dépend de votre rôle. Pour un administrateur, il affiche en plus le <strong>pilotage</strong> : la photographie chiffrée de l&#39;établissement à l&#39;instant où vous ouvrez la page.</p><p>Le pilotage est un pôle à part entière. S&#39;il n&#39;a pas été licencié pour votre établissement, vous arrivez bien sur le tableau de bord, mais sans les indicateurs décrits ci-dessous.</p><h2 id="sur-quoi-portent-les-chiffres" tabindex="-1">Sur quoi portent les chiffres <a class="header-anchor" href="#sur-quoi-portent-les-chiffres" aria-label="Permalink to &quot;Sur quoi portent les chiffres&quot;">​</a></h2><p>Tous les indicateurs se lisent pour l&#39;<strong>année scolaire courante</strong> — celle marquée comme actuelle dans <a href="/era-guide/guide/admin/structure-etablissement.html">Structure de l&#39;établissement</a>.</p><p>Si aucune année n&#39;est marquée comme courante, le tableau de bord vous le dit au lieu d&#39;afficher des chiffres : rien ne peut être calculé tant que l&#39;année de référence n&#39;est pas définie. C&#39;est le premier réflexe à avoir si la page semble vide en début d&#39;exercice.</p><h2 id="les-indicateurs" tabindex="-1">Les indicateurs <a class="header-anchor" href="#les-indicateurs" aria-label="Permalink to &quot;Les indicateurs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Indicateur</th><th>Ce qu&#39;il mesure</th></tr></thead><tbody><tr><td>Élèves inscrits</td><td>L&#39;effectif réellement inscrit sur l&#39;année courante</td></tr><tr><td>Résultats moyens</td><td>La moyenne générale de l&#39;établissement</td></tr><tr><td>Taux d&#39;absentéisme</td><td>La part d&#39;absences relevées sur les présences saisies</td></tr><tr><td>Occupation internat</td><td>Les lits attribués rapportés aux lits existants. Vide — et non 0 % — pour un site sans aucun lit</td></tr><tr><td>Montant dû</td><td>Le total facturé aux familles sur l&#39;année</td></tr><tr><td>Montant encaissé</td><td>Ce qui a réellement été payé</td></tr><tr><td>Taux de recouvrement</td><td>L&#39;encaissé rapporté au dû</td></tr><tr><td>Montant décaissé</td><td>Les dépenses approuvées de l&#39;établissement</td></tr><tr><td>Flux de trésorerie net</td><td>L&#39;encaissé moins le décaissé</td></tr></tbody></table><p>Deux précisions qui évitent les mauvaises lectures :</p><ul><li>Seuls les paiements <strong>confirmés</strong> alimentent le montant encaissé. Un paiement mobile money lancé mais pas confirmé par l&#39;opérateur n&#39;y figure pas, et ne gonfle donc jamais le taux de recouvrement.</li><li>Le montant décaissé ne compte que les dépenses <strong>approuvées</strong> — une dépense en attente de validation n&#39;est pas encore de la trésorerie sortie. Voir <a href="/era-guide/guide/caissier/depenses.html">Dépenses</a>.</li></ul><h2 id="lire-les-chiffres-site-par-site" tabindex="-1">Lire les chiffres site par site <a class="header-anchor" href="#lire-les-chiffres-site-par-site" aria-label="Permalink to &quot;Lire les chiffres site par site&quot;">​</a></h2><p>Sous les indicateurs, le bloc <strong>Par site</strong> reprend les mêmes mesures pour chaque site de l&#39;établissement, ce qui permet de comparer deux campus sans changer de page. Le sélecteur <strong>Tous les sites</strong> filtre l&#39;ensemble du tableau de bord sur un site précis.</p><p>Sur téléphone, ce tableau s&#39;affiche sous forme d&#39;une fiche par site plutôt qu&#39;en colonnes, pour rester lisible.</p><h2 id="exporter-les-chiffres" tabindex="-1">Exporter les chiffres <a class="header-anchor" href="#exporter-les-chiffres" aria-label="Permalink to &quot;Exporter les chiffres&quot;">​</a></h2><p>Le bouton <strong>Exporter le tableur</strong> télécharge l&#39;ensemble des indicateurs, détaillés par site, dans un fichier tableur. C&#39;est le format à utiliser pour un conseil d&#39;administration ou un reporting mensuel : les chiffres exportés sont exactement ceux affichés à l&#39;écran au moment de l&#39;export.</p>',15)])])}const f=t(i,[["render",n]]);export{m as __pageData,f as default};
